"use client";
import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { ArrowDownToLine, ArrowRight, ArrowUpRight, BookOpen, Bookmark, CalendarDays, ChartNoAxesCombined, Check, CheckCheck, ChevronDown, ChevronLeft, ChevronRight, CircleCheck, CircleHelp, Clock3, CloudCheck, CloudOff, Copy, FilePenLine, FileText, Flag, GraduationCap, History, LayoutDashboard, ListChecks, LoaderCircle, Menu, Pause, Play, Plus, Printer, RotateCcw, Search, Settings2, ShieldCheck, Sparkles, Target, Timer, Upload, X } from "lucide-react";
import { CONTENT_DATE, LAWS, SUBJECTS, TOPICS, UPDATE_TASKS, type AmendmentNote, type Essay, type Law, type Question, type Subject } from "../lib/study-data";
import { ALL_QUESTIONS as QUESTIONS, ALL_ESSAYS as ESSAYS, PAST_PAPERS, EXTERNAL_SCOPE, acceptedAnswers, answerLabel } from "../lib/past-exams";
