type Tab = "home"|"questions"|"laws"|"essays"|"review"|"progress"|"updates";
type Mastery = "unseen"|"mastered"|"review"|"verify";
type QProgress = { status:Mastery; bookmarked:boolean; wrong:boolean; attempts:number; correct:number; lastAnswer?:number; lastDate?:string; nextReview?:string; note?:string };
type Day = { tasks:string[]; seconds:number; questions:string[]; essays:string[] };
const DEFAULT_Q:QProgress = {status:"unseen",bookmarked:false,wrong:false,attempts:0,correct:0};
const DEFAULT_DAY:Day = {tasks:[],seconds:0,questions:[],essays:[]};
const STATUSES:{id:Mastery;label:string}[]=[{id:"mastered",label:"已掌握"},{id:"review",label:"待複習"},{id:"verify",label:"需要查證"}];
const NAV:{id:Tab;label:string;icon:typeof BookOpen}[]=[{id:"home",label:"今日總覽",icon:LayoutDashboard},{id:"questions",label:"主題題庫",icon:BookOpen},{id:"laws",label:"法條速記",icon:FileText},{id:"essays",label:"申論練習",icon:FilePenLine},{id:"review",label:"錯題與收藏",icon:Bookmark},{id:"progress",label:"學習進度",icon:ChartNoAxesCombined},{id:"updates",label:"修法與函釋",icon:History}];
const dateKey=(date=new Date())=>new Intl.DateTimeFormat("en-CA",{timeZone:"Asia/Taipei",year:"numeric",month:"2-digit",day:"2-digit"}).format(date);
const addDays=(d:number)=>dateKey(new Date(Date.now()+d*86400000));
const topicName=(id:string)=>TOPICS.find(t=>t.id===id)?.name??id;
const topicColor=(id:string)=>TOPICS.find(t=>t.id===id)?.color??"indigo";
const cn=(...v:(string|false|undefined|null)[])=>v.filter(Boolean).join(" ");
function Download(data:unknown,name:string){const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
async function copyText(text:string){if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);return;}const el=document.createElement("textarea");el.value=text;document.body.appendChild(el);el.select();if(!document.execCommand("copy")){el.remove();throw new Error("copy");}el.remove();}
function Pill({children,tone="neutral"}:{children:ReactNode;tone?:string}){return <span className={cn("pill",tone)}>{children}</span>}
function Empty({title,description,action}:{title:string;description:string;action?:ReactNode}){return <div className="empty"><div className="empty-icon"><BookOpen size={28}/></div><h3>{title}</h3><p>{description}</p>{action}</div>}
function Dialog({children,onClose,title,wide=false}:{children:ReactNode;onClose:()=>void;title:string;wide?:boolean}){const ref=useRef<HTMLDivElement>(null);const close=useRef(onClose);close.current=onClose;useEffect(()=>{const previous=document.activeElement as HTMLElement;const old=document.body.style.overflow;document.body.style.overflow="hidden";ref.current?.focus();const key=(e:KeyboardEvent)=>{if(e.key==="Escape")close.current();if(e.key==="Tab"){const items=ref.current?.querySelectorAll<HTMLElement>('button:not([disabled]), a[href], input, textarea, select, [tabindex="0"]');if(!items?.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===ref.current)){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};document.addEventListener("keydown",key);return()=>{document.body.style.overflow=old;document.removeEventListener("keydown",key);previous?.focus();};},[]);return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><div className={cn("modal",wide&&"wide")} role="dialog" aria-modal="true" aria-label={title} tabIndex={-1} ref={ref}><div className="modal-bar no-print"><span>{title}</span><button className="icon-button" aria-label="關閉視窗" onClick={onClose}><X size={21}/></button></div>{children}</div></div>}
function MasteryButtons({value,onChange}:{value:Mastery;onChange:(v:Mastery)=>void}){return <div className="mastery-group">{STATUSES.map(s=><button key={s.id} aria-pressed={value===s.id} className={cn("mastery-button",s.id,value===s.id&&"selected")} onClick={()=>onChange(value===s.id?"unseen":s.id)}>{s.id==="mastered"?<CheckCheck size={15}/>:s.id==="review"?<RotateCcw size={15}/>:<CircleHelp size={15}/>} {s.label}</button>)}</div>}

export default function StudyApp(){
  const store=useStudyStore();const {records,put,read,ready}=store;
  const [tab,setTab]=useState<Tab>("home");const [menu,setMenu]=useState(false);const [today,setToday]=useState("");
  const [query,setQuery]=useState("");const [subject,setSubject]=useState("全部科目");const [topic,setTopic]=useState("全部主題");const [mastery,setMastery]=useState("全部狀態");const [difficulty,setDifficulty]=useState("全部難度");const [verification,setVerification]=useState("全部內容");const [page,setPage]=useState(1);
  const [paperYear,setPaperYear]=useState("all");const [paperTrack,setPaperTrack]=useState("all");const [amendmentFilter,setAmendmentFilter]=useState("all");
  const [reviewMode,setReviewMode]=useState("wrong");const [lawMode,setLawMode]=useState("all");const [detail,setDetail]=useState<{kind:"question";id:string}|{kind:"law";id:string}|null>(null);
  const [practice,setPractice]=useState<string[]>([]);const [practiceIndex,setPracticeIndex]=useState(0);const [sessionResults,setSessionResults]=useState<Record<string,boolean>>({});const [sessionDone,setSessionDone]=useState(false);
  const [focusOpen,setFocusOpen]=useState(false);const [essayId,setEssayId]=useState(ESSAYS[0].id);const [settings,setSettings]=useState(false);const [customOpen,setCustomOpen]=useState(false);const [toast,setToast]=useState("");const [showSearch,setShowSearch]=useState(false);const [planType,setPlanType]=useState<"auto"|"weekday"|"weekend">("auto");
  const [timerLeft,setTimerLeft]=useState(25*60);const [timerRunning,setTimerRunning]=useState(false);const [timerDuration,setTimerDuration]=useState(25*60);const [timerTask,setTimerTask]=useState("自由專注");const timerEnd=useRef(0),focusStart=useRef(0);const latest=useRef({read,put});latest.current={read,put};
  const notify=(text:string)=>setToast(text);
  useEffect(()=>{setToday(dateKey());const hash=location.hash.slice(1) as Tab;if(NAV.some(n=>n.id===hash))setTab(hash);const id=setInterval(()=>setToday(dateKey()),60000);return()=>clearInterval(id);},[]);
  useEffect(()=>{if(toast){const id=setTimeout(()=>setToast(""),4000);return()=>clearTimeout(id);}},[toast]);
  useEffect(()=>setPage(1),[query,subject,topic,mastery,difficulty,verification,reviewMode,tab,paperYear,paperTrack,amendmentFilter]);
  const questions=useMemo(()=>[...QUESTIONS,...Object.entries(records).filter(([k,r])=>k.startsWith("custom:")&&isQuestion(r.value)).map(([,r])=>r.value as Question)],[records]);
  const essayOptions=ESSAYS.filter(e=>(paperYear==="all"||(paperYear==="practice"?!e.paperYear:e.paperYear===Number(paperYear)))&&(paperTrack==="all"||(paperTrack==="practice"?!e.paperTrack:e.paperTrack===paperTrack)));
  useEffect(()=>{if(essayOptions.length&&!essayOptions.some(e=>e.id===essayId))setEssayId(essayOptions[0].id);},[paperYear,paperTrack,essayId]);
  const qProgress=(id:string)=>read<QProgress>(`q:${id}`,DEFAULT_Q);const lawStatus=(id:string)=>read<Mastery>(`law:${id}`,"unseen");const day=read<Day>(`day:${today}`,DEFAULT_DAY);
  const taipeiDay=today?new Date(today+"T12:00:00+08:00").getUTCDay():1;const weekend=planType==="weekend"||(planType==="auto"&&(taipeiDay===0||taipeiDay===6));
  const plan=weekend?[{id:"core",title:"整理重點",minutes:15,description:"整理一個主題的要件與流程",to:"laws" as Tab},{id:"law",title:"閱讀法條與函釋",minutes:25,description:"原文逐字核對，標記版本疑點",to:"laws" as Tab},{id:"recall",title:"閉卷短背誦",minutes:20,description:"先回想，再打開法條比對",to:"laws" as Tab},{id:"quiz",title:"主題題庫與錯題",minutes:30,description:"逐項讀完解析，留下錯誤原因",to:"questions" as Tab},{id:"essay",title:"完整申論練習",minutes:30,description:"完成一題25分申論與結構自評",to:"essays" as Tab}]:[{id:"core",title:"整理重點",minutes:10,description:"先讀一個主題的核心與常考點",to:"laws" as Tab},{id:"law",title:"閱讀法條與函釋",minutes:15,description:"核對原文，再看需要查證之處",to:"laws" as Tab},{id:"recall",title:"閉卷短背誦",minutes:10,description:"用口訣回想要件、時限與程序",to:"laws" as Tab},{id:"quiz",title:"主題題庫與錯題",minutes:15,description:"練8題，對照A～D逐項解析",to:"questions" as Tab},{id:"essay",title:"申論分段練習",minutes:10,description:"按配分寫一個段落，再自我檢核",to:"essays" as Tab}];
  const targetMinutes=weekend?120:60;const todayTopic=TOPICS[(Math.floor((today?new Date(today+"T00:00:00Z"):new Date()).getTime()/86400000)+3)%8];
  const go=(next:Tab)=>{setTab(next);setPaperYear("all");setPaperTrack("all");setAmendmentFilter("all");setMenu(false);setShowSearch(false);setQuery("");setSubject("全部科目");setTopic("全部主題");setMastery("全部狀態");setVerification("全部內容");setDifficulty("全部難度");setPage(1);history.replaceState(null,"",`#${next}`);window.scrollTo({top:0,behavior:"smooth"});};
  const visitTopic=(id:string,next:Tab="questions")=>{go(next);setTopic(id);};const updateQ=(id:string,patch:Partial<QProgress>)=>put(`q:${id}`,{...qProgress(id),...patch});const toggleTask=(id:string)=>put(`day:${today}`,{...day,tasks:day.tasks.includes(id)?day.tasks.filter(x=>x!==id):[...day.tasks,id]});
  function logTime(){if(focusStart.current){const seconds=Math.max(0,Math.round((Math.min(Date.now(),timerEnd.current)-focusStart.current)/1000));const key=`day:${dateKey()}`;const d=latest.current.read<Day>(key,DEFAULT_DAY);latest.current.put(key,{...d,seconds:d.seconds+seconds});focusStart.current=0;}}
  useEffect(()=>{if(!timerRunning)return;const id=setInterval(()=>{const left=Math.max(0,Math.ceil((timerEnd.current-Date.now())/1000));setTimerLeft(left);if(left===0){logTime();setTimerRunning(false);notify("這一段專注已完成，記得勾選今日安排並稍作休息。");}},300);return()=>clearInterval(id);},[timerRunning]);
  useEffect(()=>{const flushTime=()=>{if(focusStart.current){logTime();focusStart.current=Date.now();}};window.addEventListener("pagehide",flushTime);return()=>window.removeEventListener("pagehide",flushTime);},[]);
  const toggleTimer=()=>{if(timerRunning){logTime();setTimerLeft(Math.max(0,Math.ceil((timerEnd.current-Date.now())/1000)));setTimerRunning(false);}else{const duration=timerLeft||timerDuration;setTimerLeft(duration);timerEnd.current=Date.now()+duration*1000;focusStart.current=Date.now();setTimerRunning(true);}};
  const prepareTimer=(minutes:number,label:string)=>{if(timerRunning){logTime();setTimerRunning(false);}setTimerLeft(minutes*60);setTimerDuration(minutes*60);setTimerTask(label);notify(`已設定${label}・${minutes}分鐘`);};
  const startPractice=(onlyReview=false)=>{const list=questions.filter(q=>q.verified&&(!onlyReview||(qProgress(q.id).wrong&&qProgress(q.id).status!=="mastered")||qProgress(q.id).status==="review")).sort((a,b)=>{const ap=qProgress(a.id),bp=qProgress(b.id);const score=(q:Question,p:QProgress)=>(p.status==="review"?30:0)+(p.wrong&&p.status!=="mastered"?20:0)+(q.topic===todayTopic.id?10:0)-(p.status==="mastered"?40:0)-p.attempts;return score(b,bp)-score(a,ap);}).slice(0,8);if(!list.length){notify("目前沒有已核對的待複習題，先從主題題庫開始。");go("questions");return;}setPractice(list.map(q=>q.id));setPracticeIndex(0);setSessionResults({});setSessionDone(false);setDetail({kind:"question",id:list[0].id});};
  const submitAnswer=(q:Question,answer:number)=>{const p=qProgress(q.id);const correct=acceptedAnswers(q).includes(answer);updateQ(q.id,{attempts:p.attempts+1,correct:p.correct+(correct?1:0),lastAnswer:answer,lastDate:today,wrong:p.wrong||!correct,status:!correct?"review":p.status==="unseen"?"review":p.status,nextReview:addDays(correct?3:1)});const d=latest.current.read<Day>(`day:${today}`,DEFAULT_DAY);put(`day:${today}`,{...d,questions:Array.from(new Set([...d.questions,q.id]))});if(practice.includes(q.id))setSessionResults(x=>({...x,[q.id]:correct}));};
  const setQMastery=(id:string,status:Mastery)=>updateQ(id,{status,nextReview:status==="mastered"?addDays(7):status==="review"?addDays(1):undefined});
  const attempted=questions.filter(q=>qProgress(q.id).attempts>0).length;const mastered=questions.filter(q=>qProgress(q.id).status==="mastered").length;const wrongCount=questions.filter(q=>qProgress(q.id).wrong&&qProgress(q.id).status!=="mastered").length;const reviewCount=questions.filter(q=>qProgress(q.id).status==="review").length;const totalAttempts=questions.reduce((s,q)=>s+qProgress(q.id).attempts,0);const totalCorrect=questions.reduce((s,q)=>s+qProgress(q.id).correct,0);const accuracy=totalAttempts?Math.round(totalCorrect/totalAttempts*100):0;
  const masteredLaws=LAWS.filter(l=>lawStatus(l.id)==="mastered").length;const draftedEssays=ESSAYS.filter(e=>read<any>(`essay:${e.id}`,{}).analysis?.trim()).length;
  let streak=0;if(today){for(let i=0;i<366;i++){const d=read<Day>(`day:${dateKey(new Date(new Date(today+"T12:00:00+08:00").getTime()-i*86400000))}`,DEFAULT_DAY);if(d.questions.length||d.seconds>=60||d.essays.length||d.tasks.length)streak++;else if(i>0||streak>0)break;}}
  const qMatches=(q:Question)=>{const p=qProgress(q.id);return (paperYear==="all"||(paperYear==="practice"?!q.paperYear:q.paperYear===Number(paperYear)))&&(paperTrack==="all"||(paperTrack==="practice"?!q.paperTrack:q.paperTrack===paperTrack))&&(amendmentFilter==="all"||q.amendment?.status===amendmentFilter)&&(subject==="全部科目"||q.subject===subject)&&(topic==="全部主題"||q.topic===topic)&&(mastery==="全部狀態"||p.status===mastery)&&(difficulty==="全部難度"||q.difficulty===difficulty)&&(verification==="全部內容"||(verification==="verified"?q.verified:!q.verified))&&(!query||[q.title,q.stem,topicName(q.topic),q.origin,q.paperYear?.toString()??"",q.amendment?.note??"",...q.options.map(o=>o.text),...q.lawIds.map(id=>LAWS.find(l=>l.id===id)?.title??"")].join(" ").toLowerCase().includes(query.toLowerCase()))&&(tab!=="review"||(reviewMode==="wrong"?p.wrong&&p.status!=="mastered":reviewMode==="bookmarks"?p.bookmarked:reviewMode==="review"?p.status==="review":p.status==="verify"||!q.verified));};
  const filteredQuestions=questions.filter(qMatches);const pageCount=Math.max(1,Math.ceil(filteredQuestions.length/8));const activePage=Math.min(page,pageCount);const filteredLaws=LAWS.filter(l=>(topic==="全部主題"||l.topic===topic)&&(!query||[l.title,l.subtitle,l.original,l.core,...l.points,...l.traps].join(" ").includes(query))&&(lawMode!=="unfamiliar"||lawStatus(l.id)!=="mastered")&&(lawMode!=="verify"||!l.verified||lawStatus(l.id)==="verify")&&(mastery==="全部狀態"||lawStatus(l.id)===mastery));
  const openQ=(id:string)=>{setPractice([]);setSessionDone(false);setDetail({kind:"question",id});};const print=()=>window.print();const copy=async(text:string)=>{try{await copyText(text);notify("已複製，可直接貼到筆記。");}catch{notify("無法自動複製，請選取文字後複製。");}};
  const checkedTasks=plan.filter(p=>day.tasks.includes(p.id));const plannedDone=checkedTasks.reduce((s,p)=>s+p.minutes,0);const timeText=`${String(Math.floor(timerLeft/60)).padStart(2,"0")}:${String(timerLeft%60).padStart(2,"0")}`;

  const filters=()=> <><div className="search-box filter-search"><Search size={18}/><input aria-label="搜尋題目、考點或法條" placeholder="搜尋題目、考點、法條或關鍵字…" value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<button className="icon-button" aria-label="清除搜尋" onClick={()=>setQuery("")}><X size={16}/></button>}</div><div className="filters"><select aria-label="篩選年度" value={paperYear} onChange={e=>setPaperYear(e.target.value)}><option value="all">全部年度</option>{PAST_PAPERS.map(p=><option key={p.meta.year} value={p.meta.year}>{p.meta.year}年</option>)}<option value="practice">主題練習／自建</option></select><select aria-label="篩選內外軌" value={paperTrack} onChange={e=>setPaperTrack(e.target.value)}><option value="all">全部軌道／主題</option><option value="內軌">內軌四等</option><option value="外軌">外軌四等（未設警勤）</option><option value="practice">主題練習／自建</option></select><select aria-label="篩選法規版本差異" value={amendmentFilter} onChange={e=>setAmendmentFilter(e.target.value)}><option value="all">全部版本註記</option><option value="changed">有修正／時效差異</option><option value="review">現行版本待核</option><option value="none">無修正註記</option></select><select aria-label="篩選科目" value={subject} onChange={e=>setSubject(e.target.value)}><option>全部科目</option>{SUBJECTS.map(s=><option key={s}>{s}</option>)}</select><select aria-label="篩選主題" value={topic} onChange={e=>setTopic(e.target.value)}><option value="全部主題">全部主題</option>{TOPICS.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select><select aria-label="篩選掌握狀態" value={mastery} onChange={e=>setMastery(e.target.value)}><option>全部狀態</option><option value="unseen">尚未練習</option>{STATUSES.map(s=><option key={s.id} value={s.id}>{s.label}</option>)}</select><select aria-label="篩選難度" value={difficulty} onChange={e=>setDifficulty(e.target.value)}><option>全部難度</option><option>基礎</option><option>進階</option></select><select aria-label="篩選內容查證狀態" value={verification} onChange={e=>setVerification(e.target.value)}><option>全部內容</option><option value="verified">已核對核心</option><option value="pending">原件待查證</option></select><button className="text-button" onClick={()=>{setPaperYear("all");setPaperTrack("all");setAmendmentFilter("all");setSubject("全部科目");setTopic("全部主題");setMastery("全部狀態");setDifficulty("全部難度");setVerification("全部內容");setQuery("");}}>重設篩選</button></div></>;
  const questionRows=(list:Question[])=><div className="question-list">{list.map(q=>{const p=qProgress(q.id);return <article className="question-row" key={q.id}><div className="question-number">{q.paperNumber?String(q.paperNumber).padStart(2,"0"):q.id.startsWith("mine_")?"自建":q.id.replace("q","").padStart(2,"0")}</div><button className="question-row-main" onClick={()=>openQ(q.id)}><div className="tag-line"><Pill tone={topicColor(q.topic)}>{topicName(q.topic)}</Pill><span className="subtle">{q.paperYear?`${q.paperYear}年・${q.paperTrack}`:q.difficulty}</span>{q.amendment?.status==="changed"&&<Pill tone="rose">版本變動</Pill>}{q.amendment?.status==="review"&&<Pill tone="amber">現行待核</Pill>}{q.correctionNote&&<Pill tone="blue">答案更正</Pill>}{!q.verified&&<span className="pending-dot">原件待核</span>}{p.wrong&&<span className="wrong-label">曾答錯</span>}</div><h3>{q.title}</h3><p>{q.stem}</p><div className="row-foot"><span>{q.subject}</span><span>{q.lawIds.slice(0,2).map(id=>LAWS.find(l=>l.id===id)?.title).filter(Boolean).join(" · ")}</span></div></button><div className="question-row-actions"><button className={cn("icon-button",p.bookmarked&&"bookmarked")} aria-label={p.bookmarked?"取消收藏":"收藏題目"} aria-pressed={p.bookmarked} onClick={()=>updateQ(q.id,{bookmarked:!p.bookmarked})}><Bookmark size={19} fill={p.bookmarked?"currentColor":"none"}/></button><span className={cn("status-label",p.status)}>{STATUSES.find(s=>s.id===p.status)?.label??"尚未練習"}</span><button className="icon-button open-question" aria-label={`練習${q.title}`} onClick={()=>openQ(q.id)}><ChevronRight size={19}/></button></div></article>;})}</div>;
  const timerCard=()=> <div className="focus-card"><div className="focus-label"><span><Timer size={17}/> 專注計時</span><span className="focus-dot">{timerRunning?"專注中":"準備開始"}</span></div><div className="timer-digits" aria-live="off">{timeText}</div><p>{timerTask} <span>／ {Math.round(timerDuration/60)}分鐘</span></p><div className="timer-buttons"><button className="timer-play" onClick={toggleTimer}>{timerRunning?<Pause size={16}/>:<Play size={16}/>} {timerRunning?"暫停":"開始專注"}</button><button className="timer-reset" aria-label="重設計時器" onClick={()=>{if(timerRunning){logTime();setTimerRunning(false);}setTimerLeft(timerDuration);}}><RotateCcw size={16}/></button></div><div className="timer-presets">{[10,25,30].map(m=><button key={m} className={timerDuration===m*60?"active":""} onClick={()=>prepareTimer(m,"自由專注")}>{m}分鐘</button>)}</div></div>;

  return <div className="app-shell"><a href="#main-content" className="skip-link">跳至主要內容</a><aside className={cn("sidebar",menu&&"open")}><button className="brand" onClick={()=>go("home")} aria-label="回今日總覽"><span className="brand-mark"><ShieldCheck size={25} strokeWidth={1.65}/></span><span><strong>警察特考複習站</strong><small>四等特考・我的讀書工作台</small></span></button><div className="sidebar-label">我的學習</div><nav aria-label="主要導覽">{NAV.map(n=><button key={n.id} className={cn("nav-item",tab===n.id&&"active")} aria-current={tab===n.id?"page":undefined} onClick={()=>go(n.id)}><n.icon size={19}/><span>{n.label}</span>{n.id==="review"&&wrongCount>0&&<span className="nav-count">{wrongCount}</span>}{n.id==="updates"&&<span className="nav-update-dot"/>}</button>)}</nav><div className="sidebar-divider"/><div className="sidebar-label">近期優先主題 <span>08</span></div><div className="sidebar-topics">{TOPICS.slice(0,8).map(t=><button key={t.id} onClick={()=>visitTopic(t.id)}><span className={cn("topic-dot",t.color)}/>{t.name}<ChevronRight size={13}/></button>)}</div><div className="sidebar-bottom"><div className="study-note"><span className="note-icon"><GraduationCap size={21}/></span><p>每天一點，穩穩累積。<small>平日60分鐘 · 假日120分鐘</small></p></div><button className="settings-link" onClick={()=>setSettings(true)}><Settings2 size={16}/> 設定與備份 <ChevronRight size={15}/></button><div className="sidebar-footer">個人專用複習站 <span>第44期</span></div></div></aside>{menu&&<button aria-label="關閉導覽選單" className="sidebar-overlay" onClick={()=>setMenu(false)}/>}
    <div className="workspace"><header className="topbar no-print"><div className="breadcrumb"><button className="icon-button mobile-menu" aria-label="開啟導覽選單" onClick={()=>setMenu(!menu)}><Menu size={21}/></button><span className="desktop-crumb">我的讀書工作台</span><ChevronRight size={13} className="desktop-crumb"/><strong>{NAV.find(n=>n.id===tab)?.label}</strong></div><div className="topbar-actions">{timerRunning&&<button className="running-timer" onClick={()=>setFocusOpen(true)}><Timer size={15}/>{timeText}</button>}<button className="top-search" onClick={()=>setShowSearch(true)} aria-label="全站搜尋"><Search size={17}/><span>搜尋考點</span></button><button className="icon-button" onClick={print} aria-label="列印目前頁面"><Printer size={18}/></button><button className={cn("sync-status",store.sync==="offline"&&"offline")} onClick={()=>void store.refresh()} title="點擊重試同步">{store.sync==="synced"?<CloudCheck size={16}/>:store.sync==="offline"?<CloudOff size={16}/>:<LoaderCircle size={16} className="spin"/>}<span>{store.sync==="synced"?"已同步":store.sync==="offline"?(store.storageFailed?"同步未完成":"本機已保存"):"同步中"}</span></button><div className="user-avatar" aria-label="我的複習站">44</div></div></header><main id="main-content" className="main-content">
    {tab==="home"&&<><div className="page-heading"><div><div className="eyebrow"><span className="little-line"/>正44期・四等特考</div><h1>今天，從一個考點開始。</h1><p>讀懂法條，拆解選項，練出自己的申論。</p></div><div className="date-chip"><CalendarDays size={17}/>{today?new Intl.DateTimeFormat("zh-TW",{timeZone:"Asia/Taipei",month:"long",day:"numeric",weekday:"long"}).format(new Date(today+"T12:00:00+08:00")):"今日練習"}</div></div><div className="home-hero-grid"><section className="hero-card"><div className="hero-copy"><div className="hero-label"><span/>你的每日複習計畫</div><h2>{weekend?"兩小時，把觀念串起來。":"一小時，扎實複習。"}</h2><p>沿著你的學習順序，把法條讀懂，<br className="desktop-br"/>再用題目與申論，確認自己真的記住。</p><div className="hero-meta"><span><Clock3 size={15}/>{targetMinutes}分鐘</span><span><BookOpen size={15}/>8題練習</span><span><FilePenLine size={15}/>{weekend?"1題申論":"1段申論"}</span></div><div className="hero-actions"><button className="button hero-primary" onClick={()=>startPractice()} disabled={!ready}>開始今日練習 <ArrowRight size={17}/></button><button className="hero-secondary" onClick={()=>document.getElementById("daily-plan")?.scrollIntoView({behavior:"smooth"})}>查看今日安排 <ArrowDownToLine size={15}/></button></div></div><div className="hero-illustration" aria-hidden="true"><div className="orbit orbit-one"/><div className="orbit orbit-two"/><div className="book-shadow"/><div className="illus-page back"><ShieldCheck size={30}/></div><div className="illus-page front"><span className="illus-line short"/><span className="illus-line"/><span className="illus-line"/><span className="illus-line medium"/><div className="illus-check"><Check size={18}/></div><span className="illus-line medium"/></div><span className="illus-star one">✦</span><span className="illus-star two">✧</span><div className="illus-pill"><Check size={13}/>一個考點，一步前進</div></div></section>{timerCard()}</div><div className="stats-grid"><Stat icon={<BookOpen size={20}/>} title="已練習題目" value={attempted} suffix={`/ ${questions.length}題`} meta="依實際作答紀錄累積" tone="indigo"/><Stat icon={<Target size={20}/>} title="作答正確率" value={totalAttempts?`${accuracy}%`:"—"} meta={totalAttempts?`${totalCorrect}次答對／${totalAttempts}次作答`:"開始作答後顯示"} tone="green"/><Stat icon={<Bookmark size={20}/>} title="待回顧錯題" value={wrongCount} suffix="題" meta={wrongCount?"把錯的原因讀懂，再練一次":"每道錯題都會自動留下"} tone="amber"/><Stat icon={<CalendarDays size={20}/>} title="連續學習" value={streak} suffix="天" meta="練題、申論或專注皆可累積" tone="rose"/></div><section className="past-home-callout"><div><Pill tone="indigo">已匯入歷屆原卷</Pill><h2>110～115年・四等警勤</h2><p>{PAST_PAPERS.length}份內軌原卷，{PAST_PAPERS.reduce((n,p)=>n+p.questions.length,0)}題選擇與{PAST_PAPERS.reduce((n,p)=>n+p.essays.length,0)}題申論，保留當年答案、更正及法規版本註記。</p></div><button className="button primary" onClick={()=>{go("questions");setPaperTrack("內軌");}}>進入歷屆題庫 <ArrowRight size={16}/></button></section><div className="section-title"><div><h2>優先複習主題 <span className="count-badge">8</span></h2><p>從你最近常讀的考點，接著往下練。</p></div><button className="text-button" onClick={()=>go("questions")}>全部題庫 <ArrowRight size={16}/></button></div><div className="topics-grid">{TOPICS.slice(0,8).map((t,i)=>{const qs=questions.filter(q=>q.topic===t.id);const count=qs.filter(q=>qProgress(q.id).status==="mastered").length;return <button className="topic-card" key={t.id} onClick={()=>visitTopic(t.id)}><div className="topic-card-top"><span className={cn("topic-icon",t.color)}>{[<ShieldCheck key="a" size={21}/>,<Search key="b" size={21}/>,<FileText key="c" size={21}/>,<ListChecks key="d" size={21}/>,<ShieldCheck key="e" size={21}/>,<Flag key="f" size={21}/>,<Target key="g" size={21}/>,<ArrowUpRight key="h" size={21}/>][i]}</span><ArrowUpRight size={17} className="topic-arrow"/></div><h3>{t.name}</h3><p>{t.short}</p><div className="topic-progress"><div className="progress-track"><span style={{width:`${qs.length?count/qs.length*100:0}%`}}/></div><span>{count}/{qs.length} 已掌握</span></div></button>;})}</div><div className="home-bottom-grid"><section className="panel daily-plan" id="daily-plan"><div className="panel-header"><h2><ListChecks size={19}/>今日安排</h2><select aria-label="每日計畫模式" value={planType} onChange={e=>setPlanType(e.target.value as typeof planType)}><option value="auto">依星期自動安排</option><option value="weekday">平日・60分鐘</option><option value="weekend">假日・120分鐘</option></select></div><div className="plan-summary"><span>已完成 {checkedTasks.length} / 5 項</span><span>{plannedDone} / {targetMinutes} 分鐘安排</span></div><div className="progress-track"><span style={{width:`${plannedDone/targetMinutes*100}%`}}/></div><div className="plan-list">{plan.map((p,i)=><div className={cn("plan-item",day.tasks.includes(p.id)&&"done")} key={p.id}><button className="check-box" aria-label={`${day.tasks.includes(p.id)?"取消完成":"標記完成"}${p.title}`} aria-pressed={day.tasks.includes(p.id)} onClick={()=>toggleTask(p.id)}>{day.tasks.includes(p.id)&&<Check size={14}/>}</button><span className="plan-step">0{i+1}</span><button className="plan-text" onClick={()=>{if(p.id==="quiz")startPractice();else if(p.id==="essay"){go("essays");setEssayId(ESSAYS.find(e=>e.topic===todayTopic.id)?.id??"s01");}else visitTopic(todayTopic.id,"laws");}}><strong>{p.title}</strong><small>{p.description}</small></button><button className="plan-time" onClick={()=>prepareTimer(p.minutes,p.title)} title="套用到專注計時"><Clock3 size={13}/>{p.minutes}分</button></div>)}</div><div className="plan-footer">今日建議主題 <button onClick={()=>visitTopic(todayTopic.id)}>{todayTopic.name}<ArrowRight size={13}/></button></div></section><div className="home-right-stack"><section className="panel recall-panel"><div className="panel-header"><h2><Sparkles size={18}/>考前一分鐘</h2><Pill tone="indigo">今日速記</Pill></div><div className="recall-title">警職法第7條</div><h3>帶往查證的三個關鍵</h3><div className="recall-points"><span><b>01</b>顯然無法查證，才得帶往。</span><span><b>02</b>三小時，自攔停起算。</span><span><b>03</b>報告中心，通知指定人。</span></div><button className="text-button" onClick={()=>setDetail({kind:"law",id:"a7"})}>看法條原文與易錯點 <ArrowRight size={16}/></button></section><section className="update-teaser"><div className="update-icon"><History size={20}/></div><div><h3>版本與答案，一起核對。</h3><p>已建立{UPDATE_TASKS.length}項待查證紀錄，保留修法與函釋欄位。</p><button onClick={()=>go("updates")}>查看查證清單 <ArrowRight size={14}/></button></div></section></div></div></>}

    {(tab==="questions"||tab==="review")&&<><div className="page-heading"><div><div className="eyebrow">{tab==="review"?"讀懂錯因，比多做一題更重要":"把法條，變成會判斷的能力"}</div><h1>{tab==="review"?"錯題與收藏":"主題題庫"}</h1><p>{tab==="review"?"答錯會自動加入；讀懂解析後，由你標記是否已掌握。":`${questions.length}題選擇題，逐項拆解A～D、錯誤文字與修正方式。`}</p></div><div className="heading-actions"><button className="button secondary" onClick={()=>setCustomOpen(true)}><Plus size={16}/>新增題目</button><button className="button primary" onClick={()=>startPractice(tab==="review")}><Play size={16}/>{tab==="review"?"重練待複習題":"每日8題"}</button></div></div>{tab==="review"&&<div className="segmented review-tabs">{[{id:"wrong",label:"待回顧錯題",count:wrongCount},{id:"bookmarks",label:"我的收藏",count:questions.filter(q=>qProgress(q.id).bookmarked).length},{id:"review",label:"待複習",count:reviewCount},{id:"verify",label:"需要查證",count:questions.filter(q=>qProgress(q.id).status==="verify"||!q.verified).length}].map(t=><button key={t.id} className={reviewMode===t.id?"active":""} onClick={()=>setReviewMode(t.id)}>{t.label}<span>{t.count}</span></button>)}</div>}{tab==="questions"&&<PastPaperOverview onYear={y=>{setPaperYear(String(y));setPaperTrack("內軌");setSubject("警察勤務");setQuery("");setMastery("全部狀態");setDifficulty("全部難度");setVerification("全部內容");setAmendmentFilter("all");setTopic("全部主題");}}/>}<section className="panel bank-panel">{filters()}<div className="list-heading"><span>共 <b>{filteredQuestions.length}</b> 題{topic!=="全部主題"?`・${topicName(topic)}`:""}</span><span>內容查證與掌握狀態分別紀錄</span></div>{filteredQuestions.length?questionRows(filteredQuestions.slice((activePage-1)*8,activePage*8)):<Empty title={paperTrack==="外軌"?"110～115年外軌四等未設警勤本科":tab==="review"?"這裡暫時沒有題目":"沒有符合條件的題目"} description={paperTrack==="外軌"?"已核對六年考選部目錄；此區不以警察法規、三等或升官等科目替代。可展開上方原卷與科目核對。":tab==="review"?"作答、收藏或標記題目後，相關紀錄會出現在這裡。":"試試另一個關鍵字，或重設篩選條件。"} action={<button className="button secondary" onClick={()=>go("questions")}>前往全部題庫</button>}/>}<div className="pagination no-print"><span>第{activePage} / {pageCount}頁</span><button className="icon-button" aria-label="上一頁題目" disabled={activePage===1} onClick={()=>setPage(activePage-1)}><ChevronLeft size={18}/></button><button className="icon-button" aria-label="下一頁題目" disabled={activePage===pageCount} onClick={()=>setPage(activePage+1)}><ChevronRight size={18}/></button></div></section></>}

    {tab==="laws"&&<><div className="page-heading"><div><div className="eyebrow">法源 → 核心 → 常考 → 易錯 → 短背誦</div><h1>法條速記</h1><p>{LAWS.length}張法條與程序卡，先讀原文，再閉卷回想。</p></div><button className="button secondary" onClick={print}><Printer size={16}/>列印目前清單</button></div><div className="segmented"><button className={lawMode==="all"?"active":""} onClick={()=>setLawMode("all")}>全部法條 <span>{LAWS.length}</span></button><button className={lawMode==="unfamiliar"?"active":""} onClick={()=>setLawMode("unfamiliar")}>尚未熟悉 <span>{LAWS.length-masteredLaws}</span></button><button className={lawMode==="verify"?"active":""} onClick={()=>setLawMode("verify")}>版本待查證</button></div><div className="law-filters no-print"><div className="search-box"><Search size={17}/><input aria-label="搜尋法條原文與重點" placeholder="搜尋法條、原文或關鍵字…" value={query} onChange={e=>setQuery(e.target.value)}/></div><select aria-label="法條主題" value={topic} onChange={e=>setTopic(e.target.value)}><option value="全部主題">全部主題</option>{TOPICS.map(t=><option value={t.id} key={t.id}>{t.name}</option>)}</select><select aria-label="法條掌握狀態" value={mastery} onChange={e=>setMastery(e.target.value)}><option>全部狀態</option><option value="unseen">尚未標記</option>{STATUSES.map(s=><option value={s.id} key={s.id}>{s.label}</option>)}</select></div><div className="law-grid">{filteredLaws.map(l=><article key={l.id} className="panel law-card"><div className="law-card-tags"><Pill tone={topicColor(l.topic)}>{topicName(l.topic)}</Pill>{!l.verified&&<Pill tone="amber">版本待查證</Pill>}</div><button className="law-card-title" onClick={()=>setDetail({kind:"law",id:l.id})}><h2>{l.title}</h2><h3>{l.subtitle}</h3></button><p className="law-core">{l.core}</p><div className="memory-strip"><span>短背誦</span>{l.memory}</div><MasteryButtons value={lawStatus(l.id)} onChange={v=>put(`law:${l.id}`,v)}/><button className="law-open" onClick={()=>setDetail({kind:"law",id:l.id})}>原文、常考與易錯點 <ArrowRight size={16}/></button></article>)}</div>{!filteredLaws.length&&<Empty title="沒有符合條件的法條" description="調整主題或關鍵字後再試一次。"/>}</>}

    {tab==="essays"&&<><div className="page-heading"><div><div className="eyebrow">先列架構，再練完整作答</div><h1>申論練習</h1><p>前言 → 依配分分段 → 法律依據與法條 → 要件／措施／程序 → 結語</p></div><button className="button secondary" onClick={print}><Printer size={16}/>列印作答</button></div><div className="essay-source-filters no-print"><select aria-label="申論年度" value={paperYear} onChange={e=>setPaperYear(e.target.value)}><option value="all">全部年度</option>{PAST_PAPERS.map(p=><option key={p.meta.year} value={p.meta.year}>{p.meta.year}年內軌</option>)}<option value="practice">主題練習</option></select><span>原卷題目保留配分；參考擬答為編寫內容，非考選部標準申論答案。</span></div><div className="essay-layout"><aside className="panel essay-list no-print"><div className="panel-header"><h2>{essayOptions.length}題申論</h2></div>{essayOptions.map(e=><button key={e.id} className={essayId===e.id?"active":""} onClick={()=>setEssayId(e.id)}><span>{e.paperYear?`${e.paperYear}年・${e.paperTrack}・申論${e.paperNumber}`:topicName(e.topic)}</span><strong>{e.title}</strong><small>{e.points}分 · {weekend?"完整練習":"可分段練習"}{read<any>(`essay:${e.id}`,{}).analysis?.trim()?" · 已有草稿":""}</small></button>)}</aside>{essayOptions.length?<EssayEditor key={essayId} essay={ESSAYS.find(e=>e.id===essayId)!} draft={read<any>(`essay:${essayId}`,{})} onChange={value=>{put(`essay:${essayId}`,value);const d=latest.current.read<Day>(`day:${today}`,DEFAULT_DAY);if(!d.essays.includes(essayId))put(`day:${today}`,{...d,essays:[...d.essays,essayId]});}} onCopy={copy} onLaw={id=>setDetail({kind:"law",id})} onTimer={()=>{prepareTimer(weekend?30:10,weekend?"完整申論":"申論分段練習");setFocusOpen(true);}}/>:<Empty title="沒有符合年度的申論" description="請選擇有原卷的年度或主題練習。"/>}</div></>}

    {tab==="progress"&&<><div className="page-heading"><div><div className="eyebrow">看見累積，也找到下一步</div><h1>學習進度</h1><p>紀錄來自你的實際作答與標記，初次使用從零開始。</p></div><button className="button secondary" onClick={()=>Download({version:1,exportedAt:new Date().toISOString(),records},`police-study-backup-${today}.json`)}><ArrowDownToLine size={16}/>匯出讀書紀錄</button></div><div className="stats-grid"><Stat icon={<CheckCheck size={20}/>} title="已掌握題目" value={mastered} suffix={`/ ${questions.length}`} meta={`已練習${attempted}題`} tone="indigo"/><Stat icon={<FileText size={20}/>} title="已熟悉法條" value={masteredLaws} suffix={`/ ${LAWS.length}`} meta="由你主動標記掌握" tone="green"/><Stat icon={<FilePenLine size={20}/>} title="已開始申論" value={draftedEssays} suffix={`/ ${ESSAYS.length}`} meta="以有分項論述文字計算" tone="amber"/><Stat icon={<Clock3 size={20}/>} title="今日專注" value={Math.floor(day.seconds/60)} suffix="分鐘" meta="計時器暫停或完成後累計" tone="rose"/></div><div className="progress-layout"><section className="panel"><div className="panel-header"><h2>四科掌握狀況</h2><span className="subtle">依已掌握題數</span></div><div className="subject-progress">{SUBJECTS.map((s,i)=>{const qs=questions.filter(q=>q.subject===s);const done=qs.filter(q=>qProgress(q.id).status==="mastered").length;return <div key={s}><div><strong>{s}</strong><span>{done}/{qs.length}題</span></div><div className="progress-track"><span style={{width:`${qs.length?done/qs.length*100:0}%`,background:["#6358d9","#399e82","#cc9c42","#6a8ecd"][i]}}/></div></div>;})}</div><div className="panel-header border-top"><h2>最近七天</h2><span className="subtle">當日練習題數</span></div><div className="activity-chart">{Array.from({length:7},(_,i)=>{const d=new Date((today?new Date(today+"T12:00:00+08:00"):new Date()).getTime()-(6-i)*86400000);const k=dateKey(d),item=read<Day>(`day:${k}`,DEFAULT_DAY);const max=Math.max(8,...Object.entries(records).filter(([k])=>k.startsWith("day:")).map(([,r])=>(r.value as Day).questions?.length??0));return <div className={k===today?"current":""} key={k}><span className="chart-value">{item.questions.length}</span><div className="bar-space"><span style={{height:`${item.questions.length?Math.max(5,item.questions.length/max*100):2}%`}}/></div><small>{Number(k.slice(5,7))}/{Number(k.slice(8))}</small></div>;})}</div></section><section className="panel"><div className="panel-header"><h2>下一步建議</h2><Target size={19}/></div><div className="next-step"><span>01</span><div><strong>回顧{wrongCount}題錯題</strong><p>先說出錯在哪，再看選項修正。</p><button className="text-button" onClick={()=>go("review")}>打開錯題 <ArrowRight size={14}/></button></div></div><div className="next-step"><span>02</span><div><strong>{LAWS.length-masteredLaws}張法條尚未標記熟悉</strong><p>閉卷背出要件及時限後再標記。</p><button className="text-button" onClick={()=>{go("laws");setLawMode("unfamiliar");}}>複習法條 <ArrowRight size={14}/></button></div></div><div className="next-step"><span>03</span><div><strong>用10分鐘練一段申論</strong><p>先把法律依據與配分架構寫對。</p><button className="text-button" onClick={()=>go("essays")}>開始申論 <ArrowRight size={14}/></button></div></div></section></div><section className="panel unfamiliar-panel"><div className="panel-header"><h2>尚未熟悉法條清單</h2><span className="subtle">未標記與待複習均列入</span></div>{LAWS.filter(l=>lawStatus(l.id)!=="mastered").map(l=><div className="unfamiliar-row" key={l.id}><button onClick={()=>setDetail({kind:"law",id:l.id})}><span className={cn("topic-dot",topicColor(l.topic))}/><strong>{l.title}</strong><span>{l.subtitle}</span></button><span className={cn("status-label",lawStatus(l.id))}>{STATUSES.find(s=>s.id===lawStatus(l.id))?.label??"尚未標記"}</span></div>)}{masteredLaws===LAWS.length&&<Empty title="目前法條都已標記熟悉" description="仍可定期抽查，確認長期記憶。"/>}</section></>}

    {tab==="updates"&&<><div className="page-heading"><div><div className="eyebrow">讓答案跟著版本一起更新</div><h1>修法與函釋</h1><p>內容核對日：{CONTENT_DATE}。這是可編輯的查證紀錄，不會自動抓取修法。</p></div></div><div className="notice"><CircleHelp size={20}/><div><strong>熟悉度與內容查證，各自保留。</strong><p>掌握題目不會自動消除版本疑點。下面的待查證項目與每題更新欄位，供你記下發布日、文號、影響及待核內容。</p></div></div><div className="updates-grid">{UPDATE_TASKS.map(t=><section className="panel update-card" key={t.id}><div className="law-card-tags"><Pill tone={topicColor(t.topic)}>{topicName(t.topic)}</Pill><Pill tone={read<any>(`update:${t.id}`,{}).completed?"green":"amber"}>{read<any>(`update:${t.id}`,{}).completed?"已完成查證紀錄":"需要查證"}</Pill></div><h2>{t.title}</h2><p>{t.detail}</p><button className="text-button" onClick={()=>setDetail({kind:"law",id:t.lawId})}>開啟相關法條卡 <ArrowRight size={14}/></button><AmendmentEditor value={read<any>(`update:${t.id}`,{})} onChange={v=>put(`update:${t.id}`,v)}/></section>)}</div><section className="panel past-updates"><div className="panel-header"><h2>歷屆警勤：修正與時效差異</h2><span className="subtle">點擊題目查看原題及對照</span></div>{QUESTIONS.filter(q=>q.amendment?.status==="changed").map(q=><button className="past-update-row" key={q.id} onClick={()=>openQ(q.id)}><Pill tone="rose">{q.paperYear}年第{q.paperNumber}題</Pill><strong>{q.title}</strong><span>{q.amendment?.note}</span><ArrowRight size={15}/></button>)}</section><div className="content-provenance"><h3>題庫內容範圍</h3><p>已建立{QUESTIONS.length}題選擇題、{LAWS.length}張法條／程序卡、{ESSAYS.length}題申論。新增110～115年內軌警勤原卷，原題、官方答案、更正與版本註記分別保存。包含你既有犯罪偵查題庫的部分原題整理及近期主題改編；未宣稱已完整匯入所有歷屆試卷。行政規則未取得完整原件的部分已標示，法條原文與整理摘要分別註明。</p></div></>}
    <footer className="page-footer"><span><ShieldCheck size={14}/>警察四等特考複習站</span><span>讀懂每一個要件，累積每一天。</span><button className="no-print" onClick={()=>setSettings(true)}>備份與設定</button></footer></main><nav className="mobile-bottom-nav no-print" aria-label="手機快捷導覽">{NAV.slice(0,5).map(n=><button key={n.id} className={tab===n.id?"active":""} onClick={()=>go(n.id)}><n.icon size={19}/><span>{n.id==="home"?"總覽":n.id==="questions"?"題庫":n.id==="laws"?"法條":n.id==="essays"?"申論":"錯題"}</span></button>)}</nav></div>

    {detail?.kind==="question"&&(()=>{const q=questions.find(q=>q.id===detail.id);if(!q)return null;return <Dialog title={practice.length?`每日練習・${practiceIndex+1}/${practice.length}`:"題目與逐項解析"} onClose={()=>{setDetail(null);setPractice([]);}} wide><QuestionDetail key={q.id} question={q} progress={qProgress(q.id)} onSubmit={answer=>submitAnswer(q,answer)} onBookmark={()=>updateQ(q.id,{bookmarked:!qProgress(q.id).bookmarked})} onMastery={status=>setQMastery(q.id,status)} onNote={note=>updateQ(q.id,{note})} onLaw={id=>{setPractice([]);setDetail({kind:"law",id});}} amendment={read<any>(`update:${q.id}`,{})} onAmendment={v=>put(`update:${q.id}`,v)} onCopy={copy} onPrint={print} practicePosition={practice.length?{index:practiceIndex,count:practice.length}:undefined} onNext={()=>{if(practiceIndex+1<practice.length){setPracticeIndex(practiceIndex+1);setDetail({kind:"question",id:practice[practiceIndex+1]});}else{setDetail(null);setSessionDone(true);}}}/></Dialog>;})()}
    {detail?.kind==="law"&&(()=>{const l=LAWS.find(l=>l.id===detail.id);if(!l)return null;return <Dialog title="法條原文與考點" onClose={()=>setDetail(null)} wide><LawDetail law={l} status={lawStatus(l.id)} onStatus={v=>put(`law:${l.id}`,v)} onCopy={copy} onPrint={print} amendment={read<any>(`update:${l.id}`,{})} onAmendment={v=>put(`update:${l.id}`,v)} onPractice={()=>{setDetail(null);visitTopic(l.topic);}}/></Dialog>;})()}
    {sessionDone&&<Dialog title="每日練習完成" onClose={()=>setSessionDone(false)}><div className="session-summary"><span className="summary-icon"><CheckCheck size={32}/></span><h2>這一輪練習完成了。</h2><p>{Object.keys(sessionResults).length}題已作答 · {Object.values(sessionResults).filter(Boolean).length}題答對 · {Object.values(sessionResults).filter(x=>!x).length}題需要再讀一次</p><div className="summary-results">{practice.map((id,i)=><span key={id} className={id in sessionResults?(sessionResults[id]?"correct":"incorrect"):"skipped"}>{String(i+1).padStart(2,"0")}{id in sessionResults?(sessionResults[id]?<Check size={14}/>:<X size={14}/>):<CircleHelp size={14}/>}</span>)}</div><p className="subtle">錯題已自動留下；答對的題目可自行標記「已掌握」。</p><button className="button primary" onClick={()=>{setSessionDone(false);go("review");}}>回顧錯題 <ArrowRight size={16}/></button></div></Dialog>}
    {showSearch&&<Dialog title="搜尋考點" onClose={()=>setShowSearch(false)}><div className="search-dialog"><div className="search-box"><Search size={19}/><input autoFocus aria-label="全站關鍵字" placeholder="輸入法條、題目或考點…" value={query} onChange={e=>setQuery(e.target.value)}/></div><p className="subtle">題目 {questions.filter(q=>query&&[q.stem,q.title,...q.options.map(o=>o.text)].join(" ").includes(query)).length}筆 · 法條 {LAWS.filter(l=>query&&[l.title,l.original,l.core].join(" ").includes(query)).length}筆</p>{!query&&<div className="quick-search">{["三小時","單一窗口","酒駕","逮捕"].map(x=><button key={x} onClick={()=>setQuery(x)}>{x}</button>)}</div>}{questions.filter(q=>query&&[q.stem,q.title,...q.options.map(o=>o.text)].join(" ").includes(query)).slice(0,5).map(q=><button className="search-result" key={q.id} onClick={()=>{setShowSearch(false);openQ(q.id);}}><BookOpen size={17}/><span>{q.title}<small>{topicName(q.topic)}</small></span><ChevronRight size={16}/></button>)}{LAWS.filter(l=>query&&[l.title,l.original,l.core].join(" ").includes(query)).slice(0,5).map(l=><button className="search-result" key={l.id} onClick={()=>{setShowSearch(false);setDetail({kind:"law",id:l.id});}}><FileText size={17}/><span>{l.title}<small>{l.subtitle}</small></span><ChevronRight size={16}/></button>)}{query&&!questions.some(q=>[q.stem,q.title,...q.options.map(o=>o.text)].join(" ").includes(query))&&!LAWS.some(l=>[l.title,l.original,l.core].join(" ").includes(query))&&<Empty title="沒有找到這個關鍵字" description="可改用法條號碼或較短的考點詞語。"/>}</div></Dialog>}
    {settings&&<Dialog title="設定與備份" onClose={()=>setSettings(false)}><div className="settings-content"><h2>把累積，好好保存。</h2><p>作答、錯題、收藏、法條熟悉度及申論草稿會自動保存，登入後同步到個人讀書紀錄。同步暫停時會保留本機版本，恢復連線後重試。</p>{store.storageFailed&&<div className="notice warning">此瀏覽器無法寫入本機儲存；請先匯出備份並確認雲端同步狀態。</div>}<div className="settings-state"><CloudCheck size={19}/><span>{store.sync==="synced"?"目前紀錄已同步":store.sync==="offline"?"雲端暫未同步，可點擊重試":"正在同步紀錄"}</span><button className="text-button" onClick={()=>void store.refresh()}>重試同步</button></div><button className="button primary full" onClick={()=>Download({version:1,exportedAt:new Date().toISOString(),records},`police-study-backup-${today}.json`)}><ArrowDownToLine size={17}/>匯出完整備份 JSON</button><label className="button secondary full import-button"><Upload size={17}/>匯入備份（合併紀錄）<input type="file" accept="application/json,.json" onChange={async e=>{try{const file=e.target.files?.[0];if(!file)return;if(file.size>3_000_000)throw new Error("too large");const data=JSON.parse(await file.text());if(data.version!==1||!data.records||Array.isArray(data.records)||typeof data.records!=="object")throw new Error("invalid");const entries=Object.entries(data.records) as [string,any][];if(entries.length>3000||entries.some(([k,r])=>!validBackupEntry(k,r)))throw new Error("invalid");let count=0;for(const[k,r]of entries){if(!records[k]||r.updatedAt>records[k].updatedAt){put(k,r.value);count++;}}notify(`已合併${count}筆較新的讀書紀錄。`);}catch{notify("匯入失敗：請使用本站匯出的有效備份檔，原有紀錄未刪除。");}finally{e.target.value="";}}}/></label><small className="subtle">匯入前會先檢查整份格式，僅合併較新的項目。下載檔可另外存到手機「檔案」。</small><div className="settings-section"><h3>每日練習的安排</h3><p>平日60分鐘、週末120分鐘，依臺灣日期判斷。今日安排可切換模式；勾選完成與實際專注時間分別紀錄。</p><h3>初始內容與核對</h3><p>{QUESTIONS.length}題選擇、{LAWS.length}張法條／程序卡、{ESSAYS.length}題申論。行政規則原件未取得者保留版本標記，並可自行新增修法與函釋紀錄。查證欄位為人工維護，不是自動法律更新。</p></div></div></Dialog>}
    {focusOpen&&<Dialog title="專注計時" onClose={()=>setFocusOpen(false)}><div className="timer-dialog">{timerCard()}<p>開始後可關閉此視窗繼續作答，計時仍會持續。</p></div></Dialog>}{customOpen&&<Dialog title="新增我的題目" onClose={()=>setCustomOpen(false)} wide><CustomQuestionEditor onSave={q=>{put(`custom:${q.id}`,q);setCustomOpen(false);go("questions");notify("已新增題目，內容預設標記為需要查證。");}}/></Dialog>}{toast&&<div className="toast" role="status"><CircleCheck size={18}/>{toast}</div>}
  </div>;
}

function Stat({icon,title,value,suffix,meta,tone}:{icon:ReactNode;title:string;value:ReactNode;suffix?:string;meta:string;tone:string}){return <section className="stat-card"><div className="stat-top"><span>{title}</span><span className={cn("stat-icon",tone)}>{icon}</span></div><div className="stat-value">{value}<small>{suffix}</small></div><p>{meta}</p></section>}

function AmendmentNotice({note}:{note?:AmendmentNote}){if(!note)return null;return <section className={cn("exam-amendment",note.status)} aria-label="法規版本註記"><div className="amendment-heading"><History size={17}/><strong>{note.status==="changed"?"修正／時效差異註記":note.status==="review"?"現行版本需要查證":"考點版本註記"}</strong>{note.date&&<span>{note.date}</span>}</div>{note.law&&<h4>{note.law}</h4>}<p>{note.note}</p>{(note.oldRule||note.newRule)&&<div className="amendment-comparison">{note.oldRule&&<div><span>考試當時／舊制</span><p>{note.oldRule}</p></div>}{note.newRule&&<div><span>現行／後續規定</span><p>{note.newRule}</p></div>}</div>}<small>核對日：{CONTENT_DATE}。未取得現行完整原件的項目，不當作現行定論。</small>{!!note.sources?.length&&<details className="amendment-source-links no-print"><summary>展開修正核對依據</summary>{note.sources.map((x,i)=><a key={i} href={x.url} target="_blank" rel="noreferrer">{x.title}<ArrowUpRight size={13}/></a>)}</details>}</section>}
function ExamSources({sources}:{sources?:{title:string;url:string}[]}){if(!sources?.length)return null;return <details className="source-details no-print"><summary>官方原卷、答案及核對連結 <ChevronDown size={15}/></summary>{sources.map((s,i)=><a key={i} href={s.url} target="_blank" rel="noreferrer">{s.title}<ArrowUpRight size={13}/></a>)}</details>}
function PastPaperOverview({onYear}:{onYear:(year:number)=>void}){return <section className="panel past-paper-overview"><div className="past-overview-heading"><div><div className="eyebrow">110～115年・四等警察勤務概要</div><h2>歷屆原卷題庫</h2><p>原題、當年度官方答案、考選部更正與修法註記分開保留。</p></div><Pill tone="indigo">{PAST_PAPERS.reduce((n,p)=>n+p.questions.length,0)}選擇＋{PAST_PAPERS.reduce((n,p)=>n+p.essays.length,0)}申論</Pill></div><div className="paper-year-buttons">{PAST_PAPERS.map(p=><button key={p.meta.year} onClick={()=>onYear(p.meta.year)}><strong>{p.meta.year}年</strong><span>內軌四等 · {p.questions.length}題</span><ArrowRight size={14}/></button>)}</div><div className="external-scope-note"><CircleHelp size={16}/><p>110～115年外軌四等行政警察均未設「警察勤務概要」。本區未以其他科目、三等或升官等題目替代。</p></div><details className="paper-source-table no-print"><summary>內外軌原卷與科目核對 <ChevronDown size={15}/></summary><div className="table-scroll"><table><thead><tr><th>年度</th><th>內軌四等警勤</th><th>外軌四等行政警察</th></tr></thead><tbody>{PAST_PAPERS.map(p=>{const external=EXTERNAL_SCOPE.find(e=>e.year===p.meta.year);return <tr key={p.meta.year}><th>{p.meta.year}</th><td><a href={`/exam-papers/${p.meta.year}/question.pdf`} target="_blank" rel="noreferrer">站內原卷</a><a href={p.meta.questionUrl} target="_blank" rel="noreferrer">官方原卷</a><a href={p.meta.answerUrl} target="_blank" rel="noreferrer">標準答案</a>{p.meta.correctionUrl&&<a href={p.meta.correctionUrl} target="_blank" rel="noreferrer">{[110,111].includes(p.meta.year)?"最終清冊":"更正公告"}</a>}</td><td>未設本科 <a href={external?.indexUrl} target="_blank" rel="noreferrer">官方目錄</a></td></tr>;})}</tbody></table></div>{EXTERNAL_SCOPE.map(e=><details className="external-year-detail" key={e.year}><summary>{e.year}年外軌實際科目</summary><p>{e.subjects.join("；")}</p></details>)}<small>申論參考擬答為本站編寫，並非考選部公布標準答案。原題按年度保留，不因重複考點刪除。</small></details></section>}
function AmendmentEditor({value,onChange}:{value:any;onChange:(v:any)=>void}){return <details className="amendment-editor no-print"><summary><History size={15}/>修法／函釋更新欄位<ChevronDown size={15}/></summary><div className="amendment-fields"><div className="form-two"><label>發布／生效日期<input type="date" value={value.date??""} onChange={e=>onChange({...value,date:e.target.value})}/></label><label>法規版本／函釋文號<input placeholder="例如：發布機關、文號" value={value.reference??""} onChange={e=>onChange({...value,reference:e.target.value})}/></label></div><label>影響內容、待核問題與修正方式<textarea rows={3} placeholder="記下受影響條文、選項、舊答案與新答案；未核對前保留疑點。" value={value.note??""} onChange={e=>onChange({...value,note:e.target.value})}/></label><label className="checkbox-label"><input type="checkbox" checked={!!value.completed} onChange={e=>onChange({...value,completed:e.target.checked})}/>我已核對原件並完成本筆查證紀錄</label><small>這個勾選記錄你的查證，不會改寫初始題目或原文。</small></div></details>}

function QuestionDetail({question:q,progress:p,onSubmit,onBookmark,onMastery,onNote,onLaw,amendment,onAmendment,onCopy,onPrint,practicePosition,onNext}:{question:Question;progress:QProgress;onSubmit:(n:number)=>void;onBookmark:()=>void;onMastery:(s:Mastery)=>void;onNote:(s:string)=>void;onLaw:(id:string)=>void;amendment:any;onAmendment:(v:any)=>void;onCopy:(s:string)=>void;onPrint:()=>void;practicePosition?:{index:number;count:number};onNext:()=>void}){
  const [selected,setSelected]=useState<number|null>(null);const [revealed,setRevealed]=useState(false);const [answered,setAnswered]=useState(false);const [note,setNote]=useState(p.note??"");const letter=(n:number)=>String.fromCharCode(65+n);const answers=acceptedAnswers(q);const right=selected!==null&&answers.includes(selected);
  const plain=()=>`${q.title}\n${q.stem}\n${q.options.map((o,i)=>`${letter(i)}. ${o.text}`).join("\n")}\n答案：${answerLabel(q)}${q.paperYear?"（當年度官方最終答案）":""}\n${q.options.map((o,i)=>`${letter(i)}：${q.paperYear?"選項判讀":o.trueStatement?"敘述正確":"敘述錯誤"}。${o.explanation}\n修正：${o.correction}`).join("\n")}\n短背誦：${q.takeaway}${q.amendment?`\n版本註記：${q.amendment.note}\n舊制：${q.amendment.oldRule??"—"}\n現行／後續規定：${q.amendment.newRule??"—"}`:""}`;
  return <div className="detail-content question-detail"><div className="detail-top"><div className="tag-line"><Pill tone={topicColor(q.topic)}>{topicName(q.topic)}</Pill><span className="subtle">{q.subject} · {q.difficulty}</span></div><div className="detail-tools no-print"><button className={cn("icon-button",p.bookmarked&&"bookmarked")} onClick={onBookmark} aria-label={p.bookmarked?"取消收藏":"收藏這題"}><Bookmark size={19} fill={p.bookmarked?"currentColor":"none"}/></button><button className="icon-button" aria-label="複製題目與解析" onClick={()=>onCopy(plain())}><Copy size={18}/></button><button className="icon-button" aria-label="列印這題" onClick={onPrint}><Printer size={18}/></button></div></div><h2>{q.title}</h2><p className="question-origin">{q.origin}</p>{q.paperYear&&<div className="historical-grading"><FileText size={16}/><span>依{q.paperYear}年官方最終答案計分；現行規定另看版本註記。</span></div>}{q.correctionNote&&<div className="notice official-correction"><History size={18}/><div><strong>官方答案更正</strong><p>{q.correctionNote}</p>{q.creditedAll&&<p>本題一律給分，不代表四個選項的敘述皆正確。</p>}</div></div>}<AmendmentNotice note={q.amendment}/>{!q.verified&&!q.paperYear&&<div className="notice warning"><CircleHelp size={18}/><p>{q.paperYear?"本題原卷與官方答案已核對；現行規範的未核事項請看版本註記。此題暫不列入每日8題的自動選題。":"本題保留舊版架構或暫定解析，現行完整原件仍待核對。此題不列入每日8題的自動選題。"}</p></div>}<div className="question-stem">{q.stem}</div><div className="answer-options">{q.options.map((o,i)=><button key={i} disabled={revealed} className={cn("answer-option",selected===i&&"chosen",revealed&&!q.creditedAll&&answers.includes(i)&&"correct",revealed&&selected===i&&!answers.includes(i)&&"incorrect")} aria-pressed={selected===i} onClick={()=>setSelected(i)}><span className="option-letter">{letter(i)}</span><span>{o.text}</span>{revealed&&!q.creditedAll&&answers.includes(i)&&<Check size={19}/>}</button>)}</div>{!revealed?<div className="answer-submit no-print"><button className="button primary" disabled={selected===null} onClick={()=>{if(selected===null)return;onSubmit(selected);setRevealed(true);setAnswered(true);}}>確認答案 <ArrowRight size={16}/></button><button className="text-button" onClick={()=>setRevealed(true)}>直接看解析（不計作答）</button></div>:<section className="explanation-section"><div className={cn("answer-result",answered?(right?"correct":"incorrect"):"neutral")}><span>{answered?(q.creditedAll?"本題依公告給分":right?"判斷正確":"這個考點再讀一次"):"參考答案"}</span><strong>{q.paperYear?"當年度答案":"答案"} {answerLabel(q)}</strong><span>{q.creditedAll?"一律給分・仍應逐項閱讀解析":q.paperYear?"保留當年度公告，不視為現行答案":"本題選出「"+q.target+"」的敘述"}</span></div><h3>A～D逐項解析</h3><div className="option-analyses">{q.options.map((o,i)=><article className={cn("option-analysis",!q.creditedAll&&answers.includes(i)&&"answer")} key={i}><div className="option-analysis-title"><span>{letter(i)}</span><strong>{o.text}</strong><Pill tone={q.paperYear?(answers.includes(i)?"blue":"neutral"):o.trueStatement?"green":"rose"}>{q.paperYear?(q.creditedAll?"一律給分題":answers.includes(i)?"官方答案":"選項判讀"):o.trueStatement?"敘述正確":"敘述錯誤"}</Pill></div><p><b>{q.paperYear?"逐項解析":o.trueStatement?"判斷依據":"錯誤原因"}：</b>{o.explanation}</p><p className="correction"><b>修正方式：</b>{o.correction}</p></article>)}</div><div className="takeaway"><Sparkles size={18}/><div><span>這題短背誦</span><strong>{q.takeaway}</strong></div></div></section>}<section className="detail-section"><h3>相關法律依據</h3><div className="related-laws">{q.lawIds.map(id=>{const l=LAWS.find(l=>l.id===id);return l?<button key={id} onClick={()=>onLaw(id)}><FileText size={15}/>{l.title}<ArrowUpRight size={14}/></button>:null;})}</div></section><section className="detail-section no-print"><h3>這題的掌握狀態 <small>與內容查證分開紀錄</small></h3><MasteryButtons value={p.status} onChange={onMastery}/><label className="note-label">我的錯因筆記<textarea rows={3} placeholder="例如：把三小時誤記為到所起算，下次先圈起算點。" value={note} onChange={e=>{setNote(e.target.value);onNote(e.target.value);}}/></label></section><ExamSources sources={q.sources}/><AmendmentEditor value={amendment} onChange={onAmendment}/>{practicePosition&&<div className="practice-next no-print"><span>第{practicePosition.index+1} / {practicePosition.count}題</span><button className="button primary" disabled={!revealed} onClick={onNext}>{practicePosition.index+1===practicePosition.count?"完成本輪":"下一題"}<ArrowRight size={16}/></button></div>}</div>;
}

function LawDetail({law:l,status,onStatus,onCopy,onPrint,amendment,onAmendment,onPractice}:{law:Law;status:Mastery;onStatus:(s:Mastery)=>void;onCopy:(s:string)=>void;onPrint:()=>void;amendment:any;onAmendment:(v:any)=>void;onPractice:()=>void}){const [hide,setHide]=useState(false);return <div className="detail-content law-detail"><div className="detail-top"><Pill tone={topicColor(l.topic)}>{topicName(l.topic)}</Pill><div className="detail-tools no-print"><button className="icon-button" aria-label="複製法條與重點" onClick={()=>onCopy(`${l.title}｜${l.subtitle}\n一、${l.originalLabel}\n${l.original}\n二、核心內容\n${l.core}\n三、常考點\n${l.points.join("\n")}\n四、易錯點\n${l.traps.join("\n")}\n五、短背誦\n${l.memory}`)}><Copy size={18}/></button><button className="icon-button" aria-label="列印法條" onClick={onPrint}><Printer size={18}/></button></div></div><h2>{l.title}</h2><p className="detail-subtitle">{l.subtitle}</p><div className="version-line"><Pill tone={l.verified?"green":"amber"}>{l.verified?"原文已核對":"完整版本待查證"}</Pill><span>{l.version}</span></div>{!l.verified&&<div className="notice warning"><CircleHelp size={18}/><p>{l.verificationNote}</p></div>}<section className="law-original"><div className="law-original-heading"><h3>01 <span>{l.originalLabel}</span></h3><button className="text-button no-print" onClick={()=>setHide(!hide)}>{hide?"顯示原文":"遮住原文背誦"}</button></div><div className={cn("original-text",hide&&"hidden-recall")}>{hide?<div><BookOpen size={24}/><strong>先閉卷回想，再顯示原文比對。</strong><button className="text-button" onClick={()=>setHide(false)}>顯示原文</button></div>:l.original}</div></section><section className="detail-section"><h3><span className="section-number">02</span>核心內容</h3><p>{l.core}</p></section><div className="law-two-columns"><section className="detail-section"><h3><span className="section-number">03</span>常考點</h3><ul>{l.points.map(x=><li key={x}>{x}</li>)}</ul></section><section className="detail-section traps"><h3><span className="section-number">04</span>易錯點</h3><ul>{l.traps.map(x=><li key={x}>{x}</li>)}</ul></section></div><div className="takeaway"><Sparkles size={20}/><div><span>05 短背誦</span><strong>{l.memory}</strong></div></div><section className="detail-section scenario"><h3>情境練習 <small>教學情境，非真實新聞</small></h3><p>{l.scenario}</p></section><section className="detail-section no-print"><h3>這條我熟悉了嗎？</h3><MasteryButtons value={status} onChange={onStatus}/></section><AmendmentEditor value={amendment} onChange={onAmendment}/><details className="source-details no-print"><summary>版本核對與原文連結 <ChevronDown size={15}/></summary><p>{l.verificationNote}</p>{l.sources.map(s=><a key={s.url} href={s.url} target="_blank" rel="noreferrer">{s.title}<ArrowUpRight size={14}/></a>)}<small>核對日：{CONTENT_DATE}。整理摘要不取代原件。</small></details><div className="detail-bottom no-print"><button className="button primary" onClick={onPractice}>練習這個主題 <ArrowRight size={16}/></button></div></div>}

function EssayEditor({essay:e,draft,onChange,onCopy,onLaw,onTimer}:{essay:Essay;draft:any;onChange:(v:any)=>void;onCopy:(s:string)=>void;onLaw:(id:string)=>void;onTimer:()=>void}){
  const [model,setModel]=useState(false);const allocation=e.allocation.map((a,i)=>`${i+1}、${a.title}（${a.points}分）`).join("\n");const fields=[{key:"intro",label:"前言",placeholder:"先用2～3句點出爭點、法源與權益。"},{key:"allocation",label:"依配分分段",placeholder:allocation},{key:"basis",label:"法律依據與法條",placeholder:"列出適用法律、條號及關鍵原文；注意規範版本。"},{key:"analysis",label:"要件／措施／程序",placeholder:"依配分段落，逐項寫出發動要件、可採措施、程序及本案涵攝。"},{key:"conclusion",label:"結語",placeholder:"回扣題意，以依法行政、比例原則及人民權益保障收束。"}];const versionText=e.amendment?`\n\n版本註記：${e.amendment.note}\n舊制：${e.amendment.oldRule??"—"}\n現行／後續規定：${e.amendment.newRule??"—"}`:"";const text=fields.map(f=>`${f.label}\n${draft[f.key]??(f.key==="allocation"?allocation:"")}`).join("\n\n");const words=fields.reduce((s,f)=>s+[...(draft[f.key]??"").replace(/\s/g,"")].length,0);const checks:string[]=draft.checks??[];
  return <section className="panel essay-editor"><div className="essay-heading"><Pill tone={topicColor(e.topic)}>{topicName(e.topic)}</Pill><span>{e.points}分</span></div><h2>{e.title}</h2><div className="essay-prompt">{e.prompt}</div>{e.paperYear&&<p className="essay-origin">{e.origin??`${e.paperYear}年內軌四等・申論第${e.paperNumber}題`}・原卷題目已核，擬答為編寫參考。</p>}<AmendmentNotice note={e.amendment}/>{!e.verified&&<div className="notice warning"><CircleHelp size={18}/><p>本題完整行政規則原件仍待核，參考擬答供架構練習，正式背誦前請補核版本細節。</p></div>}<div className="allocation-chips">{e.allocation.map(a=><span key={a.title}>{a.title}<b>{a.points}分</b></span>)}</div><div className="essay-toolbar no-print"><button className="text-button" onClick={onTimer}><Timer size={16}/>設定練習計時</button><button className="text-button" onClick={()=>onCopy(`${e.title}\n${e.prompt}\n\n${text}${versionText}`)}><Copy size={15}/>複製我的作答</button><span>草稿自動保存 · {words}字</span></div><div className="essay-fields">{fields.map((f,i)=><label key={f.key}><span className="essay-field-label"><b>0{i+1}</b>{f.label}{f.key==="analysis"&&<small>依各段配分調整篇幅</small>}</span><textarea rows={f.key==="analysis"?9:f.key==="intro"||f.key==="conclusion"?3:4} placeholder={f.placeholder} value={draft[f.key]??(f.key==="allocation"?allocation:"")} onChange={ev=>onChange({...draft,[f.key]:ev.target.value})}/><div className="print-only essay-print-text">{draft[f.key]??(f.key==="allocation"?allocation:"（尚未作答）")}</div></label>)}</div><div className="self-check no-print"><h3><ListChecks size={18}/>結構檢核（自評）<span>{checks.length}/{e.checklist.length}</span></h3>{e.checklist.map(c=><label key={c}><input type="checkbox" checked={checks.includes(c)} onChange={()=>onChange({...draft,checks:checks.includes(c)?checks.filter(x=>x!==c):[...checks,c]})}/>{c}</label>)}<small>結構檢核不代表內容正確或正式閱卷分數，仍須對照法律原文。</small></div><div className="essay-model-control no-print"><button className="button secondary" onClick={()=>setModel(!model)}><BookOpen size={16}/>{model?"收起參考擬答":"展開參考擬答"}<ChevronDown size={15}/></button><span>建議先寫，再看答案。</span></div>{model&&<div className="essay-model"><h3>參考擬答</h3><h4>前言</h4><p>{e.model.intro}</p><h4>依配分分段</h4><p>{allocation}</p><h4>法律依據與法條</h4><p>{e.model.basis}</p><h4>要件／措施／程序</h4><p>{e.model.analysis}</p><h4>結語</h4><p>{e.model.conclusion}</p><button className="text-button no-print" onClick={()=>onCopy(`${e.title}\n前言\n${e.model.intro}\n依配分分段\n${allocation}\n法律依據與法條\n${e.model.basis}\n要件／措施／程序\n${e.model.analysis}\n結語\n${e.model.conclusion}${versionText}`)}><Copy size={15}/>複製參考擬答</button></div>}<ExamSources sources={e.sources}/><section className="detail-section"><h3>對照法條原文</h3><div className="related-laws">{e.lawIds.map(id=><button key={id} onClick={()=>onLaw(id)}><FileText size={15}/>{LAWS.find(l=>l.id===id)?.title}<ArrowUpRight size={14}/></button>)}</div></section></section>;
}

function isQuestion(q:any):q is Question{return q&&typeof q.id==="string"&&/^[a-zA-Z0-9_-]+$/.test(q.id)&&typeof q.title==="string"&&typeof q.stem==="string"&&SUBJECTS.includes(q.subject)&&TOPICS.some(t=>t.id===q.topic)&&Array.isArray(q.options)&&q.options.length===4&&q.options.every((o:any)=>o&&typeof o.text==="string"&&typeof o.explanation==="string"&&typeof o.correction==="string"&&typeof o.trueStatement==="boolean")&&Number.isInteger(q.answer)&&q.answer>=0&&q.answer<4&&Array.isArray(q.lawIds)&&q.lawIds.every((id:any)=>typeof id==="string")&&typeof q.origin==="string"&&typeof q.takeaway==="string"&&typeof q.verified==="boolean"&&["正確","錯誤"].includes(q.target)&&["基礎","進階"].includes(q.difficulty);}
function validBackupEntry(k:string,r:any){if(!/^(q|law|essay|day|update|settings|custom):[a-zA-Z0-9_-]{1,100}$/.test(k)||!r||typeof r.updatedAt!=="number"||!("value"in r))return false;if(k.startsWith("custom:"))return isQuestion(r.value);if(k.startsWith("day:"))return Array.isArray(r.value?.questions)&&Array.isArray(r.value?.tasks)&&Array.isArray(r.value?.essays)&&typeof r.value.seconds==="number";if(k.startsWith("q:"))return ["unseen","mastered","review","verify"].includes(r.value?.status)&&typeof r.value.attempts==="number"&&typeof r.value.correct==="number";if(k.startsWith("law:"))return ["unseen","mastered","review","verify"].includes(r.value);if(k.startsWith("essay:"))return r.value&&typeof r.value==="object"&&["intro","allocation","basis","analysis","conclusion"].every(f=>r.value[f]===undefined||typeof r.value[f]==="string")&&(r.value.checks===undefined||Array.isArray(r.value.checks));return r.value&&typeof r.value==="object";}
function CustomQuestionEditor({onSave}:{onSave:(q:Question)=>void}){const [title,setTitle]=useState("");const [stem,setStem]=useState("");const [subject,setSubject]=useState<Subject>("警察法規");const [topic,setTopic]=useState("powers");const [answer,setAnswer]=useState(0);const [target,setTarget]=useState<"正確"|"錯誤">("正確");const [takeaway,setTakeaway]=useState("");const [lawIds,setLawIds]=useState<string[]>([]);const [options,setOptions]=useState(Array.from({length:4},()=>({text:"",explanation:"",correction:""})));const [error,setError]=useState("");return <form className="custom-editor" onSubmit={ev=>{ev.preventDefault();if(!title.trim()||!stem.trim()||options.some(o=>!o.text.trim()||!o.explanation.trim()||!o.correction.trim())){setError("請填入題目、四個選項及各項解析、修正方式。敘述正確的選項可填『無須修正』。");return;}const id=`mine_${Date.now()}`;onSave({id,subject,topic,title:title.trim(),stem:stem.trim(),options:options.map((o,i)=>({...o,trueStatement:target==="正確"?i===answer:i!==answer})),answer,target,lawIds,verified:false,difficulty:"進階",origin:"我的自建題目・原件待查證",takeaway:takeaway.trim()||"請補記本題關鍵考點。"});}}><h2>新增題目與四項解析</h2><p>自行建立的題目會保留於你的紀錄中，內容預設需要查證。</p><div className="form-two"><label>科目<select value={subject} onChange={e=>setSubject(e.target.value as Subject)}>{SUBJECTS.map(s=><option key={s}>{s}</option>)}</select></label><label>主題<select value={topic} onChange={e=>setTopic(e.target.value)}>{TOPICS.map(t=><option value={t.id} key={t.id}>{t.name}</option>)}</select></label></div><label>題目標題<input value={title} onChange={e=>setTitle(e.target.value)} required/></label><label>完整題幹<textarea value={stem} onChange={e=>setStem(e.target.value)} required rows={3}/></label><div className="form-two"><label>題目問<select value={target} onChange={e=>setTarget(e.target.value as typeof target)}><option>正確</option><option>錯誤</option></select></label><label>答案選項<select value={answer} onChange={e=>setAnswer(Number(e.target.value))}>{[0,1,2,3].map(i=><option key={i} value={i}>{String.fromCharCode(65+i)}</option>)}</select></label></div>{options.map((o,i)=><div className="custom-option" key={i}><h3>選項{String.fromCharCode(65+i)}</h3>{[{key:"text",label:"選項文字"},{key:"explanation",label:"判斷依據／錯誤原因"},{key:"correction",label:"修正方式"}].map(f=><label key={f.key}>{f.label}<textarea rows={2} value={o[f.key as keyof typeof o]} onChange={e=>setOptions(options.map((item,n)=>n===i?{...item,[f.key]:e.target.value}:item))} required/></label>)}</div>)}<label>短背誦<input value={takeaway} onChange={e=>setTakeaway(e.target.value)}/></label><label>相關法條（可複選）<select multiple value={lawIds} size={5} onChange={e=>setLawIds(Array.from(e.target.selectedOptions).map(o=>o.value))}>{LAWS.map(l=><option value={l.id} key={l.id}>{l.title}・{l.subtitle}</option>)}</select></label>{error&&<div className="notice warning">{error}</div>}<button className="button primary" type="submit"><Plus size={16}/>儲存我的題目</button></form>}
